artifacts.solve_py:
import os, csv, json, math, itertools, sys

from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"

# ---------------- load data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    CFG = json.load(f)

SETUP = CFG["first_case_setup_minutes"]
TURN = CFG["turnover_minutes"]
OT_COST = CFG["overtime_cost_per_minute"]
IDLE_COST = CFG["idle_cost_per_minute"]
WARD_OF = CFG["ward_overflow_cost_per_bed_night"]
ICU_OF = CFG["icu_overflow_cost_per_bed_night"]
PACU_OF = CFG["pacu_overflow_cost_per_bed_hour"]
MAX_OT = CFG["max_planned_overtime_minutes"]
ALPHA = CFG["tail_risk_alpha"]
TRW = CFG["tail_risk_weight"]
TARD = CFG["tardiness_cost_per_priority_day"]
DAYS = list(range(1, CFG["planning_days"] + 1))
NIGHTS = list(range(1, CFG["spillover_nights"] + 1))

def read_csv(name):
    with open(os.path.join(DATA, name)) as f:
        return list(csv.DictReader(f))

cases = read_csv("surgery_cases.csv")
blocks = read_csv("or_blocks.csv")
surgeons = read_csv("surgeons.csv")
pools = read_csv("equipment_pools.csv")
anes = read_csv("anesthesia_limits.csv")
pacu_cap = read_csv("pacu_capacity.csv")
ward_cap = read_csv("recovery_capacity.csv")
icu_cap = read_csv("icu_capacity.csv")
scens = read_csv("scenarios.csv")

C = [c["case_id"] for c in cases]
B = [b["block_id"] for b in blocks]
W = [s["scenario_id"] for s in scens]

case = {}
for c in cases:
    case[c["case_id"]] = {
        "spec": c["specialty"],
        "ready": int(c["ready_day"]),
        "due": int(c["due_day"]),
        "dur": int(c["expected_duration_min"]),
        "prio": int(c["priority_weight"]),
        "defer": float(c["defer_penalty"]),
        "anes": c["anesthesia_type"],
        "surgeon": c["primary_surgeon"],
        "pacu": int(c["pacu_minutes"]),
        "ward": c["ward"],
        "los": int(c["los_nights"]),
        "icu": c["icu_need"] == "1",
        "ped": c["pediatric"] == "1",
        "ha": c["high_acuity"] == "1",
        "inf": c["infection_flag"] == "1",
        "card": c["needs_cardiac_monitoring"] == "1",
        "pool": c["equipment_pool"],
    }

blk = {}
for b in blocks:
    blk[b["block_id"]] = {
        "day": int(b["day"]),
        "room": b["room"],
        "reg": int(b["regular_minutes"]),
        "open": float(b["open_cost"]),
        "specs": set(b["allowed_specialties"].split("|")),
        "ped": b["pediatric_capable"] == "1",
        "card": b["cardiac_capable"] == "1",
        "icu": b["icu_direct"] == "1",
        "maxc": int(b["max_cases"]),
        "maxha": int(b["max_high_acuity"]),
    }

sur = {}
for s in surgeons:
    sur[s["surgeon_id"]] = {
        "days": set(int(d) for d in s["available_days"].split("|")),
        "maxmin": int(s["max_minutes_per_day"]),
        "maxcase": int(s["max_cases_per_day"]),
    }

pool = {}
for p in pools:
    pool[p["equipment_pool"]] = {
        "units": int(p["units"]),
        "turn": int(p["turnaround_minutes"]),
        "maxuse": int(p["max_uses_per_day"]),
    }

anes_lim = {}
for a in anes:
    anes_lim[(int(a["day"]), a["anesthesia_type"])] = int(a["max_cases"])

pacu_buckets = {}  # day -> list of (start, end, cap)
for r in pacu_cap:
    d = int(r["day"])
    pacu_buckets.setdefault(d, []).append((int(r["bucket_start_minute"]), int(r["bucket_end_minute"]), int(r["capacity"])))

ward_cap_d = {}
for r in ward_cap:
    ward_cap_d[(int(r["night"]), r["ward"])] = int(r["capacity"])

icu_cap_d = {}
for r in icu_cap:
    icu_cap_d[int(r["night"])] = int(r["capacity"])

scen = {}
for s in scens:
    scen[s["scenario_id"]] = {
        "prob": float(s["probability"]),
        "fac": {"regional": float(s["regional_factor"]), "general": float(s["general_factor"]), "complex": float(s["complex_factor"])},
        "ha": int(s["high_acuity_extra_min"]),
        "eday": int(s["emergency_day"]),
        "erom": s["emergency_room"],
        "estart": int(s["emergency_start_minute"]),
        "emin": int(s["emergency_minutes"]),
        "epacu": int(s["emergency_pacu_minutes"]),
        "eward": s["emergency_ward"],
        "ewnight": int(s["emergency_ward_night"]),
        "ewbeds": int(s["emergency_ward_beds"]),
        "eicunight": int(s["emergency_icu_night"]),
        "eicubeds": int(s["emergency_icu_beds"]),
    }

def sdur(w, c):
    cc = case[c]
    f = scen[w]["fac"][cc["anes"]]
    d = cc["dur"] * f
    if cc["ha"]:
        d += scen[w]["ha"]
    return d

# eligibility
elig = {}
for c in C:
    cc = case[c]
    for b in B:
        bb = blk[b]
        if bb["day"] < cc["ready"]:
            continue
        if cc["spec"] not in bb["specs"]:
            continue
        if cc["ped"] and not bb["ped"]:
            continue
        if cc["card"] and not bb["card"]:
            continue
        if cc["icu"] and not bb["icu"]:
            continue
        if cc["dur"] > bb["reg"] + MAX_OT:
            continue
        elig.setdefault(c, []).append(b)

# ---------------- model ----------------
model = Model("surgcap")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env is not None:
    try:
        time_limit = min(time_limit, float(env))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

x = {}
p = {}
t = {}
y = {}
z = {}

TMAX = 1440
for c in C:
    z[c] = model.addVar(name="z_%s" % c, vtype="B", lb=0, ub=1, obj=case[c]["defer"])
    for b in elig.get(c, []):
        x[c, b] = model.addVar(name="x_%s_%s" % (c, b), vtype="B", lb=0, ub=1, obj=0.0)
        for k in range(1, blk[b]["maxc"] + 1):
            p[c, b, k] = model.addVar(name="p_%s_%s_%d" % (c, b, k), vtype="B", lb=0, ub=1)
        t[c, b] = model.addVar(name="t_%s_%s" % (c, b), vtype="I", lb=0, ub=TMAX)
for b in B:
    y[b] = model.addVar(name="y_%s" % b, vtype="B", lb=0, ub=1, obj=blk[b]["open"])

# assignment
for c in C:
    model.addCons(quicksum(x[c, b] for b in elig.get(c, [])) + z[c] == 1, name="assign_%s" % c)

# position <-> assignment
for c in C:
    for b in elig.get(c, []):
        model.addCons(quicksum(p[c, b, k] for k in range(1, blk[b]["maxc"] + 1)) == x[c, b], name="possum_%s_%s" % (c, b))
        for k in range(1, blk[b]["maxc"] + 1):
            model.addCons(p[c, b, k] <= x[c, b], name="posle_%s_%s_%d" % (c, b, k))
        model.addCons(t[c, b] >= SETUP * x[c, b], name="tmin_%s_%s" % (c, b))
        model.addCons(t[c, b] <= TMAX * x[c, b], name="tmax_%s_%s" % (c, b))
        # planned finish within reg + MAX_OT
        model.addCons(t[c, b] + case[c]["dur"] <= (blk[b]["reg"] + MAX_OT) * x[c, b] + TMAX * (1 - x[c, b]), name="fin_%s_%s" % (c, b))

# position uniqueness and block caps
for b in B:
    for k in range(1, blk[b]["maxc"] + 1):
        model.addCons(quicksum(p[c, b, k] for c in C if (c, b) in p) <= 1, name="uniq_%s_%d" % (b, k))
    model.addCons(quicksum(x[c, b] for c in C if (c, b) in x) <= blk[b]["maxc"] * y[b], name="cap_%s" % b)
    ha_terms = [x[c, b] for c in C if (c, b) in x and case[c]["ha"]]
    if ha_terms:
        model.addCons(quicksum(ha_terms) <= blk[b]["maxha"] * y[b], name="ha_%s" % b)
    # infection: at most one, only final position
    inf_terms = [x[c, b] for c in C if (c, b) in x and case[c]["inf"]]
    if inf_terms:
        model.addCons(quicksum(inf_terms) <= 1, name="inf1_%s" % b)
    for c in C:
        if (c, b) in x and case[c]["inf"]:
            for k in range(1, blk[b]["maxc"]):
                model.addCons(p[c, b, k] == 0, name="infpos_%s_%s_%d" % (c, b, k))

# ordering: t(c',b,k+1) >= t(c,b,k) + dur(c) + TURN
for b in B:
    for k in range(1, blk[b]["maxc"]):
        for c in C:
            if (c, b, k) not in p:
                continue
            for c2 in C:
                if (c2, b, k + 1) not in p:
                    continue
                M = TMAX
                model.addCons(t[c2, b] >= t[c, b] + case[c]["dur"] + TURN - M * (2 - p[c, b, k] - p[c2, b, k + 1]), name="ord_%s_%d_%s_%s" % (b, k, c, c2))

# surgeon constraints
for sg, sd in sur.items():
    for d in DAYS:
        cs_d = [c for c in C if case[c]["surgeon"] == sg and d in sd["days"]]
        if not cs_d:
            continue
        xs = [(c, b) for c in cs_d for b in elig.get(c, []) if blk[b]["day"] == d]
        if not xs:
            continue
        model.addCons(quicksum(x[c, b] for (c, b) in xs) <= sd["maxcase"], name="sgcase_%s_%d" % (sg, d))
        model.addCons(quicksum(case[c]["dur"] * x[c, b] for (c, b) in xs) <= sd["maxmin"], name="sgmin_%s_%d" % (sg, d))
        # pairwise no overlap
        for (c1, b1), (c2, b2) in itertools.combinations(xs, 2):
            o = model.addVar(name="ov_%s_%d_%s_%s" % (sg, d, c1, c2), vtype="B")
            M = TMAX
            model.addCons(t[c1, b1] + case[c1]["dur"] - t[c2, b2] <= M * o, name="ov1_%s_%s_%s" % (sg, c1, c2))
            model.addCons(t[c2, b2] + case[c2]["dur"] - t[c1, b1] <= M * (1 - o), name="ov2_%s_%s_%s" % (sg, c1, c2))

# anesthesia limits
for d in DAYS:
    for at in ("regional", "general", "complex"):
        lim = anes_lim.get((d, at), 0)
        xs = [(c, b) for c in C if case[c]["anes"] == at for b in elig.get(c, []) if blk[b]["day"] == d]
        if xs:
            model.addCons(quicksum(x[c, b] for (c, b) in xs) <= lim, name="anes_%d_%s" % (d, at))

# equipment pools
for gname, g in pool.items():
    for d in DAYS:
        cs_d = [c for c in C if case[c]["pool"] == gname]
        xs = [(c, b) for c in cs_d for b in elig.get(c, []) if blk[b]["day"] == d]
        if not xs:
            continue
        model.addCons(quicksum(x[c, b] for (c, b) in xs) <= g["maxuse"], name="pooluse_%s_%d" % (gname, d))
        # pairwise: either c1 finishes+turn before c2 starts, or vice versa
        for (c1, b1), (c2, b2) in itertools.combinations(xs, 2):
            o = model.addVar(name="po_%s_%d_%s_%s" % (gname, d, c1, c2), vtype="B")
            M = TMAX
            model.addCons(t[c1, b1] + case[c1]["dur"] + g["turn"] - t[c2, b2] <= M * o, name="po1_%s_%s_%s" % (gname, c1, c2))
            model.addCons(t[c2, b2] + case[c2]["dur"] + g["turn"] - t[c1, b1] <= M * (1 - o), name="po2_%s_%s_%s" % (gname, c1, c2))

# ---------------- stochastic costs ----------------
# Per scenario w, per block b: scenario finish variables fw[c,b,w]
fw = {}
for w in W:
    for b in B:
        for k in range(1, blk[b]["maxc"] + 1):
            for c in C:
                if (c, b, k) in p:
                    fw[c, b, w] = model.addVar(name="fw_%s_%s_%s" % (w, c, b), vtype="C", lb=0, ub=3000)
                    model.addCons(fw[c, b, w] >= t[c, b] + sdur(w, c), name="fwbase_%s_%s_%s" % (w, c, b))
        for k in range(1, blk[b]["maxc"]):
            for c in C:
                if (c, b, k) not in p:
                    continue
                for c2 in C:
                    if (c2, b, k + 1) not in p:
                        continue
                    model.addCons(fw[c2, b, w] >= fw[c, b, w] + TURN - 3000 * (2 - p[c, b, k] - p[c2, b, k + 1]), name="fword_%s_%s_%d_%s_%s" % (w, b, k, c, c2))

rf = {}
ot = {}
il = {}
for w in W:
    for b in B:
        rf[b, w] = model.addVar(name="rf_%s_%s" % (w, b), vtype="C", lb=0, ub=3000)
        for c in C:
            if (c, b, w) in fw:
                model.addCons(rf[b, w] >= fw[c, b, w] - 3000 * (1 - x[c, b]), name="rf_%s_%s_%s" % (w, b, c))
        sc = scen[w]
        if sc["erom"] == blk[b]["room"] and sc["eday"] == blk[b]["day"]:
            model.addCons(rf[b, w] >= sc["estart"] + sc["emin"], name="rfem_%s_%s" % (w, b))
        ot[b, w] = model.addVar(name="ot_%s_%s" % (w, b), vtype="C", lb=0, ub=3000)
        il[b, w] = model.addVar(name="il_%s_%s" % (w, b), vtype="C", lb=0, ub=3000)
        model.addCons(ot[b, w] >= rf[b, w] - blk[b]["reg"], name="ot1_%s_%s" % (w, b))
        model.addCons(il[b, w] >= blk[b]["reg"] - rf[b, w], name="il1_%s_%s" % (w, b))
        model.addCons(ot[b, w] <= 3000 * y[b], name="ot2_%s_%s" % (w, b))
        model.addCons(il[b, w] <= 3000 * y[b], name="il2_%s_%s" % (w, b))

# PACU occupancy: elective case c in block b occupies PACU on day d(b) from fw[c,b,w] for pacu minutes.
# overlap of [fw, fw+L] with bucket [s,e] linearized:
#   ov >= fw + L - e ; ov >= s - fw - L ; ov <= fw - s + L ; ov + fw <= e ; ov >= 0
pacu_ov = {}
pacu_of = {}
for w in W:
    for d in DAYS:
        for bi, (s, e, cap) in enumerate(pacu_buckets[d]):
            ov_vars = []
            for c in C:
                for b in elig.get(c, []):
                    if blk[b]["day"] != d:
                        continue
                    if (c, b, w) not in fw:
                        continue
                    L = case[c]["pacu"]
                    ov = model.addVar(name="pov_%s_%d_%d_%s_%s" % (w, d, bi, c, b), vtype="C", lb=0, ub=L)
                    pacu_ov[(w, d, bi, c, b)] = ov
                    ov_vars.append(ov)
                    model.addCons(ov >= fw[c, b, w] + L - e, name="pov1_%s_%d_%d_%s_%s" % (w, d, bi, c, b))
                    model.addCons(ov >= s - fw[c, b, w] - L, name="pov2_%s_%d_%d_%s_%s" % (w, d, bi, c, b))
                    model.addCons(ov <= fw[c, b, w] - s + L, name="pov3_%s_%d_%d_%s_%s" % (w, d, bi, c, b))
                    model.addCons(ov + fw[c, b, w] <= e, name="pov4_%s_%d_%d_%s_%s" % (w, d, bi, c, b))
            # emergency pacu in this day: occupies from estart for epacu minutes
            sc = scen[w]
            if sc["eday"] == d and sc["epacu"] > 0:
                L = sc["epacu"]
                ov = model.addVar(name="povem_%s_%d_%d" % (w, d, bi), vtype="C", lb=0, ub=L)
                a = sc["estart"]
                model.addCons(ov >= a + L - e, name="povem1_%s_%d_%d" % (w, d, bi))
                model.addCons(ov >= s - a - L, name="povem2_%s_%d_%d" % (w, d, bi))
                model.addCons(ov <= a - s + L, name="povem3_%s_%d_%d" % (w, d, bi))
                model.addCons(ov + a <= e, name="povem4_%s_%d_%d" % (w, d, bi))
                ov_vars.append(ov)
            of = model.addVar(name="pof_%s_%d_%d" % (w, d, bi), vtype="C", lb=0, ub=100)
            pacu_of[(w, d, bi)] = of
            occ = quicksum(ov_vars) if ov_vars else 0
            model.addCons(occ - of <= cap * 60.0, name="pof_%s_%d_%d" % (w, d, bi))

# ward occupancy per night: case c on day d occupies ward w(c) nights d..d+los-1
ward_of = {}
wards_all = sorted(set(case[c]["ward"] for c in C))
for w in W:
    for n in NIGHTS:
        for ward in wards_all:
            cap = ward_cap_d.get((n, ward), 0)
            occ_terms = [x[c, b] for c in C for b in elig.get(c, [])
                         if case[c]["ward"] == ward and blk[b]["day"] <= n <= blk[b]["day"] + case[c]["los"] - 1]
            sc = scen[w]
            em = 0
            if sc["eward"] == ward and sc["ewnight"] == n:
                em = sc["ewbeds"]
            of = model.addVar(name="woff_%s_%d_%s" % (w, n, ward), vtype="C", lb=0, ub=100)
            ward_of[(w, n, ward)] = of
            occ = quicksum(occ_terms) if occ_terms else 0
            model.addCons(occ + em - of <= cap, name="woff_%s_%d_%s" % (w, n, ward))

# ICU occupancy per night: icu_need cases occupy surgery day night; plus emergency
icu_of = {}
for w in W:
    for n in NIGHTS:
        cap = icu_cap_d.get(n, 0)
        occ_terms = [x[c, b] for c in C for b in elig.get(c, [])
                     if case[c]["icu"] and blk[b]["day"] == n]
        sc = scen[w]
        em = 0
        if sc["eicunight"] == n:
            em = sc["eicubeds"]
        of = model.addVar(name="icoff_%s_%d" % (w, n), vtype="C", lb=0, ub=100)
        icu_of[(w, n)] = of
        occ = quicksum(occ_terms) if occ_terms else 0
        model.addCons(occ + em - of <= cap, name="icoff_%s_%d" % (w, n))

# ---------------- objective ----------------
obj_terms = []

# lateness
for c in C:
    for b in elig.get(c, []):
        late = max(0, blk[b]["day"] - case[c]["due"])
        if late > 0:
            obj_terms.append(TARD * case[c]["prio"] * late * x[c, b])

# scenario costs
Cw = {}
for w in W:
    pi = scen[w]["prob"]
    terms = []
    for b in B:
        terms.append(pi * OT_COST * ot[b, w])
        terms.append(pi * IDLE_COST * il[b, w])
    for (ww, d, bi), of in pacu_of.items():
        terms.append(pi * PACU_OF * of / 60.0)
    for (ww, n, ward), of in ward_of.items():
        terms.append(pi * WARD_OF * of)
    for (ww, n), of in icu_of.items():
        terms.append(pi * ICU_OF * of)
    Cw[w] = quicksum(terms) if terms else 0
    obj_terms.append(Cw[w])

# tail risk: tau = probability-weighted expected scenario cost (linear threshold);
# charge excess of each scenario cost over tau.
tau = quicksum(scen[w]["prob"] * Cw[w] for w in W)
ex = {}
for w in W:
    ex[w] = model.addVar(name="ex_%s" % w, vtype="C", lb=0, ub=1e7)
    model.addCons(ex[w] >= Cw[w] - tau, name="ex_%s" % w)
    obj_terms.append(TRW * scen[w]["prob"] * ex[w])

obj_expr = quicksum(obj_terms)
model.setObjective(obj_expr, sense="minimize")

# ---------------- solve ----------------
status = "unknown"
objval = None
try:
    model.optimize()
    status = model.getStatus()
    if model.getNSols() > 0:
        objval = model.getObjVal()
except Exception as e:
    print("solve error:", e)

print("status:", status)
print("objective:", objval)
print("nsols:", model.getNSols())

# ---------------- extract solution ----------------
sol = {}  # c -> (b, k, t)
if model.getNSols() > 0:
    for c in C:
        for b in elig.get(c, []):
            v = model.getVal(x[c, b])
            if v is not None and v > 0.5:
                k = 0
                for kk in range(1, blk[b]["maxc"] + 1):
                    if model.getVal(p[c, b, kk]) > 0.5:
                        k = kk
                        break
                tv = model.getVal(t[c, b])
                sol[c] = (b, k, int(round(tv)))
                break

# ---------------- validation ----------------
def validate(sol):
    ok = True
    def fail(msg):
        nonlocal ok
        ok = False
        print("FAIL:", msg)
    byb = {}
    for c, (b, k, t0) in sol.items():
        byb.setdefault(b, []).append((c, k, t0))
    for b, lst in byb.items():
        bb = blk[b]
        if len(lst) > bb["maxc"]:
            fail("block %s too many cases" % b)
        ks = [k for _, k, _ in lst]
        if len(set(ks)) != len(ks):
            fail("block %s dup sequence" % b)
        ha = sum(1 for c, _, _ in lst if case[c]["ha"])
        if ha > bb["maxha"]:
            fail("block %s high acuity cap" % b)
        infs = [c for c, _, _ in lst if case[c]["inf"]]
        if len(infs) > 1:
            fail("block %s multiple infection" % b)
        if infs and infs[0] not in [c for c, k, _ in lst if k == max(ks)]:
            fail("block %s infection not last" % b)
        lst.sort(key=lambda r: r[1])
        prev = None
        for c, k, t0 in lst:
            if t0 < SETUP:
                fail("%s start before setup" % c)
            if t0 + case[c]["dur"] > bb["reg"] + MAX_OT:
                fail("%s planned overtime exceeded" % c)
            if prev is not None:
                pc, pk, pt = prev
                if t0 < pt + case[pc]["dur"] + TURN:
                    fail("%s ordering violation after %s" % (c, pc))
            prev = (c, k, t0)
    for sg in sur:
        for d in DAYS:
            cs = [(c, t0) for c, (b, k, t0) in sol.items() if case[c]["surgeon"] == sg and blk[b]["day"] == d]
            if len(cs) > sur[sg]["maxcase"]:
                fail("surgeon %s day %d case cap" % (sg, d))
            if sum(case[c]["dur"] for c, _ in cs) > sur[sg]["maxmin"]:
                fail("surgeon %s day %d minutes cap" % (sg, d))
            for (c1, t1), (c2, t2) in itertools.combinations(cs, 2):
                if not (t1 + case[c1]["dur"] <= t2 or t2 + case[c2]["dur"] <= t1):
                    fail("surgeon %s overlap %s/%s" % (sg, c1, c2))
    for d in DAYS:
        for at in ("regional", "general", "complex"):
            cnt = sum(1 for c, (b, k, t0) in sol.items() if case[c]["anes"] == at and blk[b]["day"] == d)
            if cnt > anes_lim.get((d, at), 0):
                fail("anesthesia %d %s cap" % (d, at))
    for gname in pool:
        for d in DAYS:
            g = pool[gname]
            cs = [(c, t0) for c, (b, k, t0) in sol.items() if case[c]["pool"] == gname and blk[b]["day"] == d]
            if len(cs) > g["maxuse"]:
                fail("pool %s day %d uses cap" % (gname, d))
            for (c1, t1), (c2, t2) in itertools.combinations(cs, 2):
                if not (t1 + case[c1]["dur"] + g["turn"] <= t2 or t2 + case[c2]["dur"] + g["turn"] <= t1):
                    fail("pool %s turnaround %s/%s" % (gname, c1, c2))
    return ok

ok = validate(sol)
